public class PaymentTerms {
    /**
     * Parses free‑text payment terms into a number of net days.
     *
     * Supported formats (case‑insensitive, surrounding whitespace ignored):
     *   - NET followed by 1‑3 digits, optional whitespace (e.g. "NET30", "net 30", "Net  45")
     *   - "DUE ON RECEIPT" → 0 days
     *
     * @param terms the raw terms string (may be null or blank)
     * @return the number of net days
     * @throws UnsupportedTermsException if the format is not recognised
     * @throws TermsOutOfRangeException  if the net days exceed 180
     */
    public static Integer parseNetDays(String terms) {
        if (terms == null) {
            throw new UnsupportedTermsException('Unsupported payment terms: null');
        }
        String trimmed = terms.trim();
        if (trimmed.length() == 0) {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
        }
        if (trimmed.equalsIgnoreCase('DUE ON RECEIPT')) {
            return 0;
        }
        // Matches NET, optional whitespace, 1‑3 digits, optional surrounding whitespace
        Pattern p = Pattern.compile('(?i)^\\s*NET\\s*(\\d{1,3})\\s*$');
        Matcher m = p.matcher(terms);
        if (m.matches()) {
            Integer days = Integer.valueOf(m.group(1));
            if (days > 180) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }
        throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
    }

    /**
     * Calculates the due date based on an invoice date and payment terms.
     *
     * @param invoiceDate the date of the invoice
     * @param terms       the payment terms string (see {@link #parseNetDays(String)})
     * @return the due date (invoiceDate + net days)
     * @throws UnsupportedTermsException if the terms are not supported
     * @throws TermsOutOfRangeException  if the net days exceed 180
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
