public class RecordSearchService {
    public class SearchException extends Exception {}

    /**
     * Searches records on any object with simple equality filters.
     *
     * @param objectApiName   API name of the object to query (case‑insensitive)
     * @param fields          List of field API names to include in addition to Id (case‑insensitive, required)
     * @param filters         Map of field API name to filter value (equality, case‑insensitive keys). May be null/empty.
     * @param orderByField    Field API name to order results by ascending (case‑insensitive). May be null/blank.
     * @param maxRows         Maximum number of rows to return (1‑200, required)
     * @return                List of SObject records matching the criteria
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---------- Validation ----------
        if (objectApiName == null || objectApiName.trim().length() == 0) {
            throw new SearchException('objectApiName must be provided');
        }

        // Get object describe (case‑insensitive)
        Schema.SObjectType objType = getObjectTypeCaseInsensitive(objectApiName);
        if (objType == null) {
            throw new SearchException('Object not found: ' + objectApiName);
        }
        System.Schema.DescribeResult objDesc = objType.getDescribe();
        if (!objDesc.isAccessible()) {
            throw new SearchException('Insufficient access to object: ' + objectApiName);
        }

        // Fields map (case‑insensitive lookup)
        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        // fields cannot be null or empty
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields list must not be null or empty');
        }

        // Validate each requested field
        List<String> actualFieldNames = new List<String>{'Id'}; // always include Id
        for (String f : fields) {
            if (f == null || f.trim().length() == 0) {
                throw new SearchException('field name in fields list cannot be null or blank');
            }
            Schema.SObjectField fld = getFieldCaseInsensitive(fieldMap, f.trim());
            if (fld == null) {
                throw new SearchException('Field not found on object: ' + f);
            }
            System.Schema.DescribeResult fDesc = fld.getDescribe();
            if (!fDesc.isAccessible()) {
                throw new SearchException('Insufficient access to field: ' + f);
            }
            actualFieldNames.add(fDesc.getName());
        }

        // Validate orderByField (if provided)
        if (orderByField != null && orderByField.trim().length() > 0) {
            Schema.SObjectField orderFld = getFieldCaseInsensitive(fieldMap, orderByField.trim());
            if (orderFld == null) {
                throw new SearchException('Order-by field not found on object: ' + orderByField);
            }
            System.Schema.DescribeResult orderDesc = orderFld.getDescribe();
            if (!orderDesc.isAccessible()) {
                throw new SearchException('Insufficient access to order-by field: ' + orderByField);
            }
            if (!orderDesc.isSortable()) {
                throw new SearchException('Field cannot be used for ordering: ' + orderByField);
            }
        }

        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200 inclusive');
        }

        // Validate filters (if any)
        if (filters != null && !filters.isEmpty()) {
            for (String fKey : filters.keySet()) {
                if (fKey == null || fKey.trim().length() == 0) {
                    throw new SearchException('filter field name cannot be null or blank');
                }
                Schema.SObjectField fld = getFieldCaseInsensitive(fieldMap, fKey.trim());
                if (fld == null) {
                    throw new SearchException('Filter field not found on object: ' + fKey);
                }
                System.Schema.DescribeResult fDesc = fld.getDescribe();
                if (!fDesc.isAccessible()) {
                    throw new SearchException('Insufficient access to filter field: ' + fKey);
                }
                if (!fDesc.isFilterable()) {
                    throw new SearchException('Field cannot be used in filter: ' + fKey);
                }
                // filter value can be any type (including null) – no further validation needed
            }
        }

        // ---------- Build SOQL ----------
        String actualObjectName = objDesc.getName(); // preserve correct case
        List<String> selectFields = new List<String>(actualFieldNames);
        String query = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + actualObjectName;

        // WHERE clause
        if (filters != null && !filters.isEmpty()) {
            List<String> whereConditions = new List<String>();
            for (String fKey : filters.keySet()) {
                Object val = filters.get(fKey);
                Schema.SObjectField fld = getFieldCaseInsensitive(fieldMap, fKey.trim());
                String fieldName = fld.getDescribe().getName();
                String literal = getSoqlLiteral(val);
                whereConditions.add(fieldName + ' = ' + literal);
            }
            query += ' WHERE ' + String.join(whereConditions, ' AND ');
        }

        // ORDER BY clause
        if (orderByField != null && orderByField.trim().length() > 0) {
            Schema.SObjectField orderFld = getFieldCaseInsensitive(fieldMap, orderByField.trim());
            String orderFieldName = orderFld.getDescribe().getName();
            query += ' ORDER BY ' + orderFieldName + ' ASC';
        }

        // LIMIT clause
        query += ' LIMIT ' + maxRows;

        // ---------- Execute ----------
        return Database.query(query);
    }

    // ---------- Helper methods ----------

    private static Schema.SObjectType getObjectTypeCaseInsensitive(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    private static Schema.SObjectField getFieldCaseInsensitive(Map<String, Schema.SObjectField> fieldMap, String fieldApiName) {
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }

    private static String getSoqlLiteral(Object value) {
        if (value == null) {
            return 'null';
        }
        if (value instanceof String) {
            return '\'' + String.escapeSingleQuotes((String)value) + '\'';
        }
        if (value instanceof Integer || value instanceof Long) {
            return String.valueOf(value);
        }
        if (value instanceof Double || value instanceof Decimal) {
            return String.valueOf(value);
        }
        if (value instanceof Boolean) {
            return ((Boolean)value) ? 'true' : 'false';
        }
        if (value instanceof Date) {
            Date d = (Date)value;
            return '\'' + d.format() + '\''; // YYYY-MM-DD
        }
        if (value instanceof DateTime) {
            // Treat as string and escape single quotes to avoid injection
            return '\'' + String.escapeSingleQuotes(((DateTime)value).format()) + '\'';
        }
        if (value instanceof Id) {
            return '\'' + ((Id)value) + '\'';
        }
        // Fallback: treat as string
        return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
    }
}
