            ev.Order_Number__c = s.orderNumber;
            ev.Tracking_Number__c = s.trackingNumber;
            ev.Carrier__c = s.carrier;
            eventsToPublish.add(ev);
        }

        if (eventsToPublish.isEmpty()) {
            return 0;
