        List<Database.SaveResult> saveResultList = EventBus.publish(eventsToPublish);
        Integer successCount = 0;
        for (Database.SaveResult sr : saveResultList) {
            if (sr.isSuccess()) {
                successCount++;
            }
        }
        return successCount;
    }
