        }

        // new records (post‑update)
        Contact new1 = new Contact(Id = old1.Id, FirstName=old1.FirstName, LastName=old1.LastName,
                                   Email='new1@example.com', HasOptedOutOfEmail=old1.HasOptedOutOfEmail);
        Contact new2 = new Contact(Id = old2.Id, FirstName=old2.FirstName, LastName=old2.LastName,
