        super(records);
    }

    public void onValidate(List<SObject> sObjects) {
        List<Opportunity> opps = (List<Opportunity>) sObjects;
        for (Opportunity o : opps) {
            // Rule 1: Amount cannot be negative (insert & update)
            if (o.Amount != null && o.Amount < 0) {
                this.addError('Amount cannot be negative.', o, Opportunity.Fields.Amount);
            }

            // Rule 2: On update, won opportunity amount cannot change
            if (Trigger.isUpdate) {
                Opportunity old = (Opportunity) Trigger.oldMap.get(o.Id);
                if (old != null && old.StageName == 'Closed Won' && o.Amount != old.Amount) {
                    this.addError('Amount cannot change on a won opportunity.', o, Opportunity.Fields.Amount);
                }
            }
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }
