public class ErpCustomerSync implements Queueable, Database.AllowsCallouts {
    private List<Id> accountIds;

    public ErpCustomerSync(List<Id> ids) {
        this.accountIds = ids;
    }

    public void execute(QueueableContext ctx) {
        // Retrieve the Accounts to be sent to ERP.
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
        ];

        if (accounts.isEmpty()) {
            return;
        }

        // Process up to 100 Accounts per execute call to stay within the 100 callout limit.
        final Integer BATCH_LIMIT = 100;
        Integer batchSize = accounts.size() > BATCH_LIMIT ? BATCH_LIMIT : accounts.size();

        for (Integer i = 0; i < batchSize; i++) {
            Account acc = accounts[i];

            // Build JSON payload: an array with a single object.
            List<Map<String, Object>> payload = new List<Map<String, Object>>();
            Map<String, Object> m = new Map<String, Object>();
            m.put('salesforceId', acc.Id);
            m.put('name', acc.Name);
            m.put('country', acc.BillingCountry == null ? null : acc.BillingCountry);
            payload.add(m);
            String jsonBody = JSON.serialize(payload);

            // Prepare and execute the callout via the Named Credential.
            HttpRequest req = new HttpRequest();
            req.setEndpoint('callout:ERP/api/customers');
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(jsonBody);

            Http http = new Http();
            try {
                HttpResponse res = http.send(req);
                // Per the ticket, we ignore the response (ERP returns 202 Accepted).
                // Any exception will propagate and be visible in Apex job logs.
            } catch (Exception e) {
                System.debug(
                    LoggingLevel.ERROR,
                    'ErpCustomerSync: Failed to send Account Id '
                    + acc.Id + ' to ERP. Error: ' + e.getMessage()
                );
            }
        }

        // If there are more Accounts left, chain another Queueable job.
        if (accounts.size() > batchSize) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = batchSize; i < accounts.size(); i++) {
                remainingIds.add(accounts[i].Id);
            }
            System.enqueueJob(new ErpCustomerSync(remainingIds));
        }
    }
}
