public with sharing class LineItemDiscountHandler {
    /**
     * Handles the before insert trigger for OpportunityLineItem.
     * When Discount is null, sets it to the standard discount for the product
     * by delegating to PricingRules.standardDiscountFor(productId).
     * The method is bulk‑safe and limits SOQL queries.
     */
    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        // 1. Collect product IDs that need a default discount (Discount == null)
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount == null && oli.Product2Id != null) {
                productIds.add(oli.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // 2. Fetch Product2 families in a single query.
        Map<Id, String> productFamilyMap = new Map<Id, String>();
        for (Product2 p : [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]) {
            productFamilyMap.put(p.Id, p.Family);
        }

        // 3. Apply discounts, calling PricingRules.standardDiscountFor for each line.
        //    To avoid duplicate SOQL calls for the same product, we cache the result
        //    after the first call per productId.
        Map<Id, Decimal> discountCache = new Map<Id, Decimal>();
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount == null && oli.Product2Id != null) {
                Id pid = oli.Product2Id;
                Decimal disc = discountCache.get(pid);
                if (disc == null) {
                    // If we have the family from our query, we can compute the discount
                    // without an extra SOQL call by using the family‑based helper.
                    // If the family is unknown (product not found or Family null),
                    // we fall back to the original method which will requery and
                    // throw the appropriate exception if needed.
                    String fam = productFamilyMap.get(pid);
                    if (fam != null) {
                        disc = PricingRules.standardDiscountForFamily(fam);
                    } else {
                        // Product not found or Family null – let the original method handle it.
                        disc = PricingRules.standardDiscountFor(pid);
                    }
                    discountCache.put(pid, disc);
                }
                oli.Discount = disc;
            }
        }
    }
}
