trigger CaseTrigger on Case (after update) {
    // Gather cases that just moved to closed and have a contact
    List<Id> newlyClosedIds = new List<Id>();
    for (Integer i = 0; i < Trigger.size; i++) {
        Case old = Trigger.old[i];
        Case neu = Trigger.new[i];
        if (!old.IsClosed && neu.IsClosed && neu.ContactId != null) {
            newlyClosedIds.add(neu.Id);
        }
    }
    if (newlyClosedIds.isEmpty()) return;

    // Enqueue in batches of <= 50 to avoid exceeding queueable job limits per transaction
    Integer batchSize = 50;
    for (Integer start = 0; start < newlyClosedIds.size(); start += batchSize) {
        Integer end = Math.min(start + batchSize, newlyClosedIds.size());
        List<Id> batch = new List<Id>();
        for (Integer idx = start; idx < end; idx++) {
            batch.add(newlyClosedIds[idx]);
        }
        System.enqueueJob(new CaseSurveyJob(batch));
    }
}
