import { LightningElement, api, track } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { open as confirmOpen } from 'lightning/confirm';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @track _opportunities = [];

    @api
    set opportunities(value) {
        // Create a shallow copy to avoid mutating the parent's array
        this._opportunities = [...value];
    }
    get opportunities() {
        return this._opportunities;
    }

    get columns() {
        return [
            { label: 'Name', fieldName: 'Name', type: 'text' },
            { label: 'Stage', fieldName: 'StageName', type: 'text' },
            {
                label: 'Amount',
                fieldName: 'Amount',
                type: 'currency',
                typeAttributes: { currencyCode: 'USD' }
            },
            {
                type: 'action',
                typeAttributes: {
                    rowActions: [
                        { label: 'View', name: 'view' },
                        { label: 'Edit', name: 'edit' },
                        { label: 'Delete', name: 'delete' }
                    ]
                }
            }
        ];
    }

    handleRowAction(event) {
        const { action, row } = event.detail;
        switch (action.name) {
            case 'view':
            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        actionName: action.name
                    }
                });
                break;
            case 'delete':
                this._handleDelete(row);
                break;
            default:
                break;
        }
    }

    async _handleDelete(row) {
        const confirmed = await confirmOpen({
            label: 'Confirm deletion',
            message: 'Are you sure you want to delete this opportunity?'
        });
        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);
            // Remove the deleted opportunity from our local copy
            this._opportunities = this._opportunities.filter(opp => opp.Id !== row.Id);
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    variant: 'success'
                })
            );
        } catch (error) {
            // Keep the row; show error toast
            const errorMessage =
                error.body?.message ||
                error.message ||
                'An unknown error occurred while deleting the opportunity.';
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    variant: 'error',
                    message: errorMessage
                })
            );
        }
    }
}
