import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        // Copy the array and each task to avoid mutating the parent's data
        this._tasks = Array.isArray(value) ? value.map(t => ({ ...t })) : [];
        this.items = this._tasks; // assign a new array
    }

    get displayedHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter(task => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel.trim();
        if (label === '') {
            return;
        }
        const newTask = { id: `new-${this.nextId++}`, label, done: false };
        // Create a new items array to trigger reactivity
        this.items = [...this.items, newTask];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;
        const idx = this.items.findIndex(t => t.id === taskId);
        if (idx >= 0) {
            const toggled = { ...this.items[idx], done: !this.items[idx].done };
            // Replace the task with a new object and assign a new items array
            this.items = [
                ...this.items.slice(0, idx),
                toggled,
                ...this.items.slice(idx + 1)
            ];
        }
    }
}
