public class HouseholdService {
    /**
     * Creates a new NPSP Household Account for the given contacts.
     * All contacts are associated with the same household, and the first contact
     * in the list is set as the household's primary contact.
     *
     * @param members List of new Contact records (no Id, no AccountId).
     * @return Id of the newly created Household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Contact list must not be null or empty.');
        }

        // Insert contacts first to obtain their Ids.
        insert members;

        // Determine the primary contact (first in the list).
        Contact primaryContact = members[0];

        // Retrieve the Household Account record type Id dynamically.
        RecordType householdRT = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = 'HH_Account'
            LIMIT 1
        ];
        if (householdRT == null) {
            throw new System.IllegalStateException('Household Account record type (HH_Account) not found.');
        }

        // Create the Household Account, setting the primary contact.
        Account household = new Account(
            RecordTypeId = householdRT.Id,
            npe01__One2OneContact__c = primaryContact.Id
            // Do not set the Name; NPSP will generate it based on the primary contact.
        );
        insert household;

        // Associate all contacts with the newly created household.
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        update members;

        return household.Id;
    }
}
